using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
namespace RebirthEntityStudio {
 // Coherent static facial-groom transfer; never edits the generated head.
 internal static class NativeFacialSurfaceFit {
  const double Smoothing=.00001;const int ControlLimit=256;
  static readonly Dictionary<NativeAppearanceHead,Context> contexts=new Dictionary<NativeAppearanceHead,Context>();
  public static void Clear(){contexts.Clear();}
  sealed class Front {
   readonly Vector3[] p;readonly int[] indices;
   public Front(Vector3[] points,int[] faces){p=points;var list=new List<int>();for(int i=0;i<faces.Length;i+=3){var n=Vector3.Cross(p[faces[i+1]]-p[faces[i]],p[faces[i+2]]-p[faces[i]]);if(n.z>n.magnitude*.08f)list.AddRange(new[]{faces[i],faces[i+1],faces[i+2]});}indices=list.ToArray();if(indices.Length==0)throw new InvalidOperationException("Native facial fit has no forward skin surface.");}
   public float Z(float x,float y){float result=float.NegativeInfinity,best=float.PositiveInfinity,edgeZ=0;var q=new Vector2(x,y);for(int i=0;i<indices.Length;i+=3){var a=p[indices[i]];var b=p[indices[i+1]];var c=p[indices[i+2]];float den=(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);if(Mathf.Abs(den)>1e-12f){float v=((x-a.x)*(c.y-a.y)-(y-a.y)*(c.x-a.x))/den,w=((b.x-a.x)*(y-a.y)-(b.y-a.y)*(x-a.x))/den;if(v>=-1e-7f&&w>=-1e-7f&&v+w<=1.0000001f)result=Mathf.Max(result,a.z+v*(b.z-a.z)+w*(c.z-a.z));}Edge(q,a,b,ref best,ref edgeZ);Edge(q,b,c,ref best,ref edgeZ);Edge(q,c,a,ref best,ref edgeZ);}return float.IsNegativeInfinity(result)?edgeZ:result;}
   static void Edge(Vector2 q,Vector3 a,Vector3 b,ref float best,ref float z){var ab=new Vector2(b.x-a.x,b.y-a.y);float t=Mathf.Clamp01(Vector2.Dot(q-new Vector2(a.x,a.y),ab)/Mathf.Max(1e-14f,ab.sqrMagnitude));var v=new Vector2(a.x,a.y)+ab*t;float d=(q-v).sqrMagnitude;if(d<best){best=d;z=Mathf.Lerp(a.z,b.z,t);}}
  }
  sealed class Context {
   public Vector3[] controls;public double[,] lu;public int[] swaps;public Front front;public float top;public Vector3[] source;public Mesh target;public double[] coefficients;public float[] scales;public float shift;
  }
  static float Percentile(float[] values,float t){Array.Sort(values);float q=(values.Length-1)*t;int i=(int)q;return Mathf.Lerp(values[i],values[Mathf.Min(i+1,values.Length-1)],q-i);}
  static float[] Widths(Vector3[] points,float top){float threshold=(points.Min(p=>p.z)+points.Max(p=>p.z))*.5f+.01f;var front=points.Where(p=>p.z>threshold).ToArray();var values=Enumerable.Repeat(float.NaN,11).ToArray();for(int i=0;i<11;i++){float y=top-(.1f+i*.02f);var row=front.Where(p=>Mathf.Abs(p.y-y)<.014f).Select(p=>Mathf.Abs(p.x)).ToArray();if(row.Length>5)values[i]=Percentile(row,.95f);}var known=Enumerable.Range(0,11).Where(i=>!float.IsNaN(values[i])).ToArray();if(known.Length<2)throw new InvalidOperationException("Insufficient facial surface for native fitting.");for(int i=0;i<11;i++)if(float.IsNaN(values[i])){int a=known.LastOrDefault(k=>k<=i),b=known.FirstOrDefault(k=>k>=i);if(i<known[0])a=b=known[0];else if(i>known[known.Length-1])a=b=known[known.Length-1];values[i]=a==b?values[a]:Mathf.Lerp(values[a],values[b],(i-a)/(float)(b-a));}return values;}
  static double Kernel(Vector3 a,Vector3 b){double x=a.x-b.x,y=a.y-b.y,r=x*x+y*y;return r<1e-24?0:.5*r*Math.Log(r);}
  static Context Prepare(NativeAppearanceHead head){var points=head.Points();float top=points.Max(p=>p.y);var candidates=points.Where(p=>p.y>top-.285f&&p.y<top-.07f&&Mathf.Abs(p.x)<.105f&&p.z>.005f).ToArray();if(candidates.Length<16)throw new InvalidOperationException("The native source does not contain enough facial controls.");int count=Mathf.Min(ControlLimit,candidates.Length);var controls=new Vector3[count];var center=candidates.Aggregate(Vector3.zero,(a,b)=>a+b)/candidates.Length;int next=Enumerable.Range(0,candidates.Length).OrderBy(i=>(candidates[i]-center).sqrMagnitude).First();var nearest=Enumerable.Repeat(float.PositiveInfinity,candidates.Length).ToArray();for(int c=0;c<count;c++){controls[c]=candidates[next];float far=-1;for(int i=0;i<candidates.Length;i++){nearest[i]=Mathf.Min(nearest[i],(candidates[i]-controls[c]).sqrMagnitude);if(nearest[i]>far){far=nearest[i];next=i;}}}int n=count+3;var matrix=new double[n,n];for(int r=0;r<count;r++){for(int c=0;c<count;c++)matrix[r,c]=Kernel(controls[r],controls[c])+(r==c?Smoothing:0);matrix[r,count]=matrix[count,r]=1;matrix[r,count+1]=matrix[count+1,r]=controls[r].x;matrix[r,count+2]=matrix[count+2,r]=controls[r].y;}var swaps=new int[n];for(int k=0;k<n;k++){int pivot=k;for(int r=k+1;r<n;r++)if(Math.Abs(matrix[r,k])>Math.Abs(matrix[pivot,k]))pivot=r;if(Math.Abs(matrix[pivot,k])<1e-13)throw new InvalidOperationException("Native facial cage is singular.");swaps[k]=pivot;if(pivot!=k)for(int c=0;c<n;c++){double t=matrix[k,c];matrix[k,c]=matrix[pivot,c];matrix[pivot,c]=t;}for(int r=k+1;r<n;r++){matrix[r,k]/=matrix[k,k];for(int c=k+1;c<n;c++)matrix[r,c]-=matrix[r,k]*matrix[k,c];}}return new Context{controls=controls,lu=matrix,swaps=swaps,front=new Front(points,head.triangles),top=top,source=points};}
  static double[] Solve(Context context,double[] rhs){int n=rhs.Length;var b=(double[])rhs.Clone();for(int k=0;k<n;k++)if(context.swaps[k]!=k){double t=b[k];b[k]=b[context.swaps[k]];b[context.swaps[k]]=t;}for(int r=0;r<n;r++)for(int c=0;c<r;c++)b[r]-=context.lu[r,c]*b[c];for(int r=n-1;r>=0;r--){for(int c=r+1;c<n;c++)b[r]-=context.lu[r,c]*b[c];b[r]/=context.lu[r,r];}return b;}
  static float Scale(Context c,float y,out float derivative){float u=(c.top-y-.1f)/.02f;if(u<=0){derivative=0;return c.scales[0];}if(u>=10){derivative=0;return c.scales[10];}int i=(int)u;derivative=-(c.scales[i+1]-c.scales[i])/.02f;return Mathf.Lerp(c.scales[i],c.scales[i+1],u-i);}
  static void Update(Context c,Mesh target){if(c.target==target)return;var all=target.vertices;var points=target.GetTriangles(0).Distinct().Select(i=>all[i]).ToArray();float top=points.Max(p=>p.y);c.shift=top-c.top;var a=Widths(c.source,c.top);var b=Widths(points,top);c.scales=a.Select((v,i)=>b[i]/v).ToArray();if(c.scales.Any(s=>s<.4f||s>1.8f))throw new InvalidOperationException("Face proportions exceed native facial-hair fit bounds.");Front surface;
   // Use original vertex indices for the projected target surface; avoid welding
   // coincident chart vertices or changing any head topology.
   surface=new Front(all,target.GetTriangles(0));var rhs=new double[c.controls.Length+3];for(int i=0;i<c.controls.Length;i++){var p=c.controls[i];float derivative;float x=p.x*Scale(c,p.y,out derivative);rhs[i]=surface.Z(x,p.y+c.shift)-c.front.Z(p.x,p.y);}c.coefficients=Solve(c,rhs);c.target=target;
  }
  public static NativeFittedVertices Fit(NativeAppearanceHead source,Mesh target,NativeFittedVertices data,Mesh original){Context c;if(!contexts.TryGetValue(source,out c))contexts[source]=c=Prepare(source);Update(c,target);int count=data.positions.Length/3;if(count!=original.vertexCount)throw new InvalidOperationException("Native facial vertex count changed.");var normals=original.normals;var tangents=original.tangents;var result=new NativeFittedVertices{name=data.name,positions=new float[count*3],normals=new float[count*3],tangents=new float[count*4]};int n=c.controls.Length;for(int i=0;i<count;i++){var p=new Vector3(data.positions[i*3],data.positions[i*3+1],data.positions[i*3+2]);double z=c.coefficients[n]+c.coefficients[n+1]*p.x+c.coefficients[n+2]*p.y,dx=c.coefficients[n+1],dy=c.coefficients[n+2];for(int k=0;k<n;k++){double x=p.x-c.controls[k].x,y=p.y-c.controls[k].y,r=x*x+y*y;if(r<1e-24)continue;double log=Math.Log(r),weight=c.coefficients[k];z+=weight*.5*r*log;dx+=weight*(log+1)*x;dy+=weight*(log+1)*y;}float slope,sx=Scale(c,p.y,out slope);var q=new Vector3(p.x*sx,p.y+c.shift,p.z+(float)z);var normal=normals[i];float nz=normal.z,nx=(normal.x-(float)dx*nz)/sx;normal=new Vector3(nx,normal.y-p.x*slope*nx-(float)dy*nz,nz).normalized;var t=tangents[i];var tangent=new Vector3(sx*t.x+p.x*slope*t.y,t.y,(float)dx*t.x+(float)dy*t.y+t.z);tangent=(tangent-normal*Vector3.Dot(tangent,normal)).normalized;for(int axis=0;axis<3;axis++){result.positions[i*3+axis]=q[axis];result.normals[i*3+axis]=normal[axis];result.tangents[i*4+axis]=tangent[axis];}result.tangents[i*4+3]=t.w;}return result;}
 }
}
